  if (bp->trackball) gltrackball_free (bp->trackball);
  for (i = 0; i < bp->ngears; i++)
    if (bp->gears[i])
      free_gear (bp->gears[i]);
  if (glIsList(bp->armature_dlist))
    glDeleteLists (bp->armature_dlist, 1);

}

XSCREENSAVER_MODULE ("Gears", gears)

